export interface AppliedCommand {
  readonly changedAt: DateTime.Utc;
  readonly result: ApplyCommandResult;
  /** Empty when nothing was persisted. */
  readonly stageChanges: readonly StageChange[];
}

const notFound = () =>
  new SalesPipelineNotFound({
    code: 'sales_pipeline_not_found',
    reason: 'Opportunity does not exist in the authorized scope',
  });

const closedOpportunity = () =>
  new SalesPipelineLifecycleConflict({
    code: 'sales_pipeline_lifecycle_conflict',
    reason: 'A closed Opportunity cannot change',
  });

const transitionNotAllowed = () =>
  new SalesPipelineLifecycleConflict({
    code: 'sales_pipeline_lifecycle_conflict',
    reason: 'The requested Opportunity transition is not allowed',
  });

const identityInUse = () =>
  new SalesPipelineRevisionConflict({
    code: 'sales_pipeline_revision_conflict',
    reason: 'Opportunity identity is already in use',
  });

const invalidOpportunityIdentity = (cause: unknown) =>
  Object.defineProperty(
    new SalesPipelineScopeMismatch({
      code: 'sales_pipeline_scope_mismatch',
      reason: 'Opportunity identity must be valid',
    }),
    'cause',
    { enumerable: false, value: cause },
  );

/** Open stages move to any other stage, WON and LOST included. WON and LOST are terminal. */
const canMoveTo = (from: OpportunityStage, to: OpportunityStage) => isOpenStage(from) && to !== from;

const moveToStage = (opportunity: Opportunity, toStage: OpportunityStage, now: DateTime.Utc): Opportunity => {
  const moved: Opportunity = {
    ...opportunity,
    probability: defaultProbabilityByStage[toStage],
    stage: toStage,
    stageHistory: [...opportunity.stageHistory, { at: now, stage: toStage }],
    updatedAt: now,
  };
  return isOpenStage(toStage) ? moved : { ...moved, closedAt: now };
};

const withOwner = (opportunity: Opportunity, owner: Option.Option<EmployeeId>, now: DateTime.Utc): Opportunity => {
  const base = { ...Struct.omit(opportunity, ['ownerEmployeeId']), updatedAt: now };
  return Option.match(owner, {
    onNone: () => base,
    onSome: (ownerEmployeeId) => ({ ...base, ownerEmployeeId }),
  });
};

const withPatch = (opportunity: Opportunity, patch: OpportunityPatch, now: DateTime.Utc): Opportunity => {
  const next = { ...opportunity, ...patch, updatedAt: now };
  return patch.lines === undefined ? next : { ...next, amountMinor: opportunityAmountMinor(patch.lines) };
};

const newOpportunity = (value: CommandOf<'CreateOpportunity'>, id: OpportunityId, now: DateTime.Utc): Opportunity => {
  const stage = value.stage ?? 'LEAD';
  const base: Opportunity = {
    amountMinor: opportunityAmountMinor(value.lines),
    createdAt: now,
    currency: 'CZK',
    expectedCloseDate: value.expectedCloseDate,
    id,
    lines: value.lines,
    partyId: value.partyId,
    probability: value.probability ?? defaultProbabilityByStage[stage],
    stage,
    stageHistory: [{ at: now, stage }],
    title: value.title,
    updatedAt: now,
  };
  const entrusted =
    value.entrustedPrincipalRef === undefined ? base : { ...base, entrustedPrincipalRef: value.entrustedPrincipalRef };
  const closed = isOpenStage(stage) ? entrusted : { ...entrusted, closedAt: now };
  const withNote = value.note === undefined ? closed : { ...closed, note: value.note };
  return value.ownerEmployeeId === undefined ? withNote : { ...withNote, ownerEmployeeId: value.ownerEmployeeId };
};

const findOpportunity = Effect.fn('SalesPipeline.findOpportunity')(function* findOpportunity(
  state: SalesPipelineState,
  id: OpportunityId,
) {
  const found = state.opportunities.find((entry) => entry.id === id);
  if (found === undefined) {
    return yield* notFound();
  }
  return found;
});

const replaceOpportunity = (state: SalesPipelineState, next: Opportunity): SalesPipelineState => ({
  ...state,
  opportunities: state.opportunities.map((entry) => (entry.id === next.id ? next : entry)),
});

const singleResult = (
  state: SalesPipelineState,
  next: Opportunity,
  stageChanges: readonly StageChange[],
): EvolvedOpportunities => ({
  affected: [next],
  stageChanges,
  state: replaceOpportunity(state, next),
});

/** One id of a bulk command: the changed opportunity, or the reason it was skipped. */
const bulkStep = (
  opportunity: Opportunity,
  patch: BulkOpportunityPatch,
  now: DateTime.Utc,
): Result.Result<Opportunity, BulkSkipReason> => {
  if (!isOpenStage(opportunity.stage)) {
    return Result.fail('closed' as const);
  }
  const { ownerEmployeeId, stage } = patch;
  if (stage !== undefined && !canMoveTo(opportunity.stage, stage)) {
    return Result.fail('invalid_transition' as const);
  }
  const moved = stage === undefined ? opportunity : moveToStage(opportunity, stage, now);
  const ownerUnchanged =
    ownerEmployeeId === undefined || Option.getOrUndefined(ownerEmployeeId) === opportunity.ownerEmployeeId;
  return Result.succeed(ownerUnchanged ? moved : withOwner(moved, ownerEmployeeId, now));
};

/** Applies a bulk command per id. Missing, closed or invalid ids are skipped with a reason; nothing throws per id. */
const evolveBulkOpportunityState = (
  state: SalesPipelineState,
  command: CommandOf<'BulkUpdateOpportunities'>,
  now: DateTime.Utc,
): EvolvedOpportunities => {
  const current = new Map(state.opportunities.map((entry) => [entry.id, entry] as const));
  const affected = new Map<OpportunityId, Opportunity>();
  const stageChanges: StageChange[] = [];
  const results = command.ids.map((id): BulkOpportunityResult => {
    const existing = current.get(id);
    if (existing === undefined) {
      return { id, outcome: 'skipped', reason: 'not_found' };
    }
    const step = bulkStep(existing, command.patch, now);
    if (Result.isFailure(step)) {
      return { id, outcome: 'skipped', reason: step.failure };
    }
    if (step.success === existing) {
      return { id, outcome: 'skipped' };
    }
    current.set(id, step.success);
    affected.set(id, step.success);
    if (step.success.stage !== existing.stage) {
      stageChanges.push({ fromStage: Option.some(existing.stage), opportunity: step.success });
    }
    return { id, outcome: 'changed' };
  });
  return {
    affected: [...affected.values()],
    results,
    stageChanges,
    state: { ...state, opportunities: state.opportunities.map((entry) => current.get(entry.id) ?? entry) },
  };
};

const createOpportunity = Effect.fn('SalesPipeline.createOpportunity')(function* createOpportunity(
  context: EvolveInput & { readonly state: SalesPipelineState },
  value: CommandOf<'CreateOpportunity'>,
) {
  const { invocationId, now, state } = context;
  // The opportunity id is the action invocation id, so a retried invocation resolves to the same identity.
  const id = yield* Schema.decodeEffect(OpportunityIdSchema)(invocationId).pipe(
    Effect.mapError(invalidOpportunityIdentity),
  );
  if (state.opportunities.some((entry) => entry.id === id)) {
    return yield* identityInUse();
  }
  const created = newOpportunity(value, id, now);
  const change: EvolvedOpportunities = {
    affected: [created],
    stageChanges: [{ fromStage: Option.none(), opportunity: created }],
    state: { ...state, opportunities: [...state.opportunities, created] },
  };
  return change;
});

const updateOpportunity = Effect.fn('SalesPipeline.updateOpportunity')(function* updateOpportunity(
  state: SalesPipelineState,
  command: CommandOf<'UpdateOpportunity'>,
  now: DateTime.Utc,
) {
  const existing = yield* findOpportunity(state, command.id);
  if (!isOpenStage(existing.stage)) {
    return yield* closedOpportunity();
  }
  return singleResult(state, withPatch(existing, command.patch, now), []);
});

const assignOpportunity = Effect.fn('SalesPipeline.assignOpportunity')(function* assignOpportunity(
  state: SalesPipelineState,
  command: CommandOf<'AssignOpportunity'>,
  now: DateTime.Utc,
) {
  const existing = yield* findOpportunity(state, command.id);
  if (!isOpenStage(existing.stage)) {
    return yield* closedOpportunity();
  }
  return singleResult(state, withOwner(existing, command.ownerEmployeeId, now), []);
});

const changeOpportunityStage = Effect.fn('SalesPipeline.changeOpportunityStage')(function* changeOpportunityStage(
  state: SalesPipelineState,
  command: CommandOf<'ChangeOpportunityStage'>,
  now: DateTime.Utc,
) {
  const existing = yield* findOpportunity(state, command.id);
  if (!isOpenStage(existing.stage)) {
    return yield* closedOpportunity();
  }
  if (!canMoveTo(existing.stage, command.toStage)) {
    return yield* transitionNotAllowed();
  }
  const moved = moveToStage(existing, command.toStage, now);
  return singleResult(state, moved, [{ fromStage: Option.some(existing.stage), opportunity: moved }]);
});

/**
 * Pure state machine for every opportunity command. Single-record commands fail the whole command on the first
 * violation; BulkUpdateOpportunities reports per-id outcomes instead.
 */
export const evolveOpportunityState = Effect.fn('SalesPipeline.evolveState')(function* evolveOpportunityState(
  state: SalesPipelineState,
  command: SalesPipelineCommand,
  input: EvolveInput,
) {
  return yield* Match.value(command).pipe(
    Match.tag('BulkUpdateOpportunities', (bulk) => Effect.succeed(evolveBulkOpportunityState(state, bulk, input.now))),
    Match.tag('CreateOpportunity', (value) => createOpportunity({ ...input, state }, value)),
    Match.tag('UpdateOpportunity', (value) => updateOpportunity(state, value, input.now)),
    Match.tag('AssignOpportunity', (value) => assignOpportunity(state, value, input.now)),
    Match.tag('ChangeOpportunityStage', (value) => changeOpportunityStage(state, value, input.now)),
    Match.tag(
      'ArchiveOpportunity',
      Effect.fn('SalesPipeline.archiveOpportunity')(function* archiveOpportunity(
        value: CommandOf<'ArchiveOpportunity'>,
      ) {
        const existing = yield* findOpportunity(state, value.id);
        if (isOpenStage(existing.stage)) {
          return yield* transitionNotAllowed();
        }
        // Preserve the record, stage history and Core Action audit; archiving never emits a sale/win event.
        return singleResult(state, { ...existing, archivedAt: input.now, updatedAt: input.now }, []);
      }),
    ),
    // AI approval commands need the caller's identity and permission checks, so persistence runs them.
    Match.tag('AiProposeChanges', 'AiDecideChanges', 'AiRevertBatch', () =>
      Effect.fail(
        new SalesPipelineLifecycleConflict({
          code: 'sales_pipeline_lifecycle_conflict',
          reason: 'AI approval commands run only through persistence',
        }),
      ),
    ),
    Match.exhaustive,
  );
});

const recordsCarrier = {
  accessDeclaration: {
    ...salesPipelineRecordsReadDeclaration,
    key: AccessKeySchema.make(salesPipelineRecordsReadDeclaration.key),
  },
};
const writeCarrier = {
  accessDeclaration: {
    ...salesPipelineApplyCommandDeclaration,
    key: AccessKeySchema.make(salesPipelineApplyCommandDeclaration.key),
  },
};

export interface SalesPipelineRecordsGrants {
  readonly predicate?: ListAccessPredicate;
  readonly readAll: boolean;
  readonly writeAll: boolean;
}
export const salesPipelineRecordsGrants = Effect.fn('SalesPipeline.recordsGrants')(function* recordsGrants(
  scope: OperationalScope,
) {
  if (scope.legalEntityId === undefined) {
    return yield* referenceUnavailable();
  }
  const gate = yield* AccessDecisionGate;
  const question = { legalEntityScope: 'required' as const, now: yield* DateTime.nowAsDate, scope };
  const { read, write } = yield* Effect.all(
    {
      read: gate.list({ ...question, carrier: recordsCarrier }),
      write: gate.decide({ ...question, carrier: writeCarrier }),
    },
    { concurrency: 1 },
  );
  if (read.decision.outcome === 'UNAVAILABLE' || write.outcome === 'UNAVAILABLE') {
    return yield* referenceUnavailable();
  }
  const predicate = read.decision.outcome === 'ALLOWED' ? read.predicate : undefined;
  const grants = { readAll: predicate?.groups.length === 0, writeAll: write.outcome === 'ALLOWED' };
  return predicate === undefined ? grants : { ...grants, predicate };
});

export const visibleOpportunities = (
  opportunities: readonly Opportunity[],
  scope: OperationalScope,
  grants: SalesPipelineRecordsGrants,
) => {
  const { predicate } = grants;
  return Effect.succeed(
    predicate === undefined ? [] : opportunities.filter((row) => opportunityVisible(predicate, row, scope.tenantId)),
  );
};

/** The stored pipeline row as the owner transaction read it (still encoded). */
export type LoadedSalesPipelineRecords = Option.Option<{ readonly revision: number; readonly state: unknown }>;

/** After commit: decodes the stored pipeline, keeps what the person may see (SpiceDB row filter), shapes the response. */
export const finishSalesPipelineRecords = Effect.fn('SalesPipeline.finishRecords')(function* finishRecords(
  request: RecordsRequest,
  loaded: LoadedSalesPipelineRecords,
  grants: SalesPipelineRecordsGrants,
  scope: OperationalScope,
) {
  const state: SalesPipelineState = Option.isNone(loaded)
    ? { opportunities: [] }
    : yield* Schema.decodeUnknownEffect(SalesPipelineStateSchema)(loaded.value.state).pipe(
        Effect.mapError(unavailable),
      );
  const visible = yield* visibleOpportunities(
    state.opportunities.filter((item) => item.archivedAt === undefined),
    scope,
    grants,
  );
  const requestedIds = request.ids === undefined ? undefined : new Set(request.ids);
  const items = visible.filter(
    (opportunity) =>
      (requestedIds === undefined || requestedIds.has(opportunity.id)) &&
      (request.stage === undefined || opportunity.stage === request.stage) &&
      (request.ownerEmployeeId === undefined || opportunity.ownerEmployeeId === request.ownerEmployeeId) &&
      (request.partyId === undefined || opportunity.partyId === request.partyId),
  );
  const response: RecordsResponse = {
    actorPrincipalRef: { principalId: scope.principalId, tenantId: scope.tenantId },
    canWrite: grants.writeAll && isConnectionWriteAllowed(scope, salesPipelineModuleId),
    indicators: opportunityIndicators(items),
    items,
    revision: Option.isSome(loaded) ? loaded.value.revision : 0,
  };
  if (grants.readAll && state.aiChanges !== undefined) {
    return { ...response, aiChanges: state.aiChanges };
  }
  return response;
});

interface PipelineStatePersistence {
  readonly insert: (
    state: typeof SalesPipelineStateSchema.Encoded,
  ) => Effect.Effect<readonly { readonly revision: number }[], SalesPipelinePersistenceUnavailable>;
  readonly load: Effect.Effect<LoadedSalesPipelineRecords, SalesPipelinePersistenceUnavailable>;
  readonly update: (
    state: typeof SalesPipelineStateSchema.Encoded,
    revision: number,
  ) => Effect.Effect<readonly { readonly revision: number }[], SalesPipelinePersistenceUnavailable>;
}
/** Reads stay side-effect free; the first successful Action creates revision one atomically. */
export const salesPipelineStateRepository = (persistence: PipelineStatePersistence) => ({
  load: Effect.fn('SalesPipeline.load')(function* load() {
    const row = yield* persistence.load;
    if (Option.isNone(row)) {
      return { revision: 0, state: { opportunities: [] } satisfies SalesPipelineState };
    }
    const state = yield* Schema.decodeUnknownEffect(SalesPipelineStateSchema)(row.value.state).pipe(
      Effect.mapError(unavailable),
    );
    return { revision: row.value.revision, state };
  }),
  save: Effect.fn('SalesPipeline.save')(function* save(expectedRevision: number, state: SalesPipelineState) {
    const encoded = yield* Schema.encodeEffect(SalesPipelineStateSchema)(state).pipe(Effect.mapError(unavailable));
    const updated = yield* persistence.update(encoded, expectedRevision);
    if (updated.length === 1) {
      return expectedRevision + 1;
    }
    if (expectedRevision === 0 && (yield* persistence.insert(encoded)).length === 1) {
      return 1;
    }
    return yield* new SalesPipelineRevisionConflict({
      code: 'sales_pipeline_revision_conflict',
      reason: revisionConflictReason,
    });
  }),
});

const entrustedPrincipalOf = (command: SalesPipelineCommand) =>
  Match.value(command).pipe(
    Match.tag('CreateOpportunity', (value) => Option.fromUndefinedOr(value.entrustedPrincipalRef)),
    Match.tag('UpdateOpportunity', (value) => Option.fromUndefinedOr(value.patch.entrustedPrincipalRef)),
    Match.orElse(Option.none<NonNullable<Opportunity['entrustedPrincipalRef']>>),
    Option.getOrUndefined,
  );

/** Authorize only this decoded command, outside its final business transaction. */
export const prepareSalesPipelineCommand = Effect.fn('SalesPipeline.prepareCommand')(function* prepareCommand(
  command: SalesPipelineCommand,
  scope: OperationalScope,
) {
  if (scope.legalEntityId === undefined) {
    return yield* referenceUnavailable();
  }
  const grants = yield* salesPipelineRecordsGrants(scope);
  const proposing = Predicate.isTagged(command, 'AiProposeChanges');
  if (!(proposing ? grants.readAll : grants.writeAll)) {
    return yield* new SalesPipelinePermissionDenied({
      code: 'sales_pipeline_permission_denied',
      reason: 'The command requires Sales Pipeline write authority',
    });
  }
  const entrusted = entrustedPrincipalOf(command);
  if (entrusted !== undefined && entrusted.tenantId !== scope.tenantId) {
    return yield* new SalesPipelineScopeMismatch({
      code: 'sales_pipeline_scope_mismatch',
      reason: 'Entrustment belongs to another tenant',
    });
  }
  if (entrusted !== undefined) {
    const snapshot = yield* loadAssignmentPreflightSnapshot(
      { ...scope, legalEntityId: scope.legalEntityId },
      () => Effect.void,
    ).pipe(Effect.mapError(referenceUnavailable));
    yield* resolveAssignee(snapshot.directory, entrusted, { carrier: recordsCarrier, scope }).pipe(
      Effect.catchTags({
        AssignablePrincipalsUnavailable: (cause) => Effect.fail(referenceUnavailable(cause)),
        AssigneeIneligible: () =>
          Effect.fail(
            new SalesPipelineReferenceIneligible({
              code: 'sales_pipeline_reference_ineligible',
              reason: 'The entrusted principal has no active read access in this company',
            }),
          ),
      }),
    );
  }
  return yield* Effect.void;
});

const sameCommand = Schema.toEquivalence(SalesPipelineCommandSchema);

export const persistenceService = Effect.fn('SalesPipeline.persistenceService')(
  function* makePersistence(
    transaction: ScopedTransactionExecutor,
    options: {
      readonly prepared?: { readonly actionInvocationId: string; readonly payload: ApplyCommandPayload };
      readonly scope: OperationalScope;
    },
  ) {
    const { prepared, scope } = options;
    const { legalEntityId } = scope;
    if (
      legalEntityId === undefined ||
      transaction.scope.tenantId !== scope.tenantId ||
      transaction.scope.legalEntityId !== legalEntityId
    ) {
      return yield* new SalesPipelineScopeMismatch({
        code: 'sales_pipeline_scope_mismatch',
        reason: 'A scoped company transaction is required',
      });
    }
    const whereScope = and(
      eq(salesPipelineStates.tenantId, scope.tenantId),
      eq(salesPipelineStates.legalEntityId, legalEntityId),
    );
    const { load, save } = salesPipelineStateRepository({
      insert: (state) =>
        DateTime.now.pipe(
          Effect.flatMap((now) =>
            transaction
              .insert(salesPipelineStates)
              .values({
                legalEntityId,
                revision: 1,
                state,
                tenantId: scope.tenantId,
                updatedAt: DateTime.toDateUtc(now),
              })
              .onConflictDoNothing()
              .returning({ revision: salesPipelineStates.revision })
              .pipe(Effect.mapError(unavailable)),
          ),
        ),
      load: transaction
        .select()
        .from(salesPipelineStates)
        .where(whereScope)
        .limit(1)
        .pipe(
          Effect.mapError(unavailable),
          Effect.map(([row]) => Option.fromUndefinedOr(row)),
        ),
      update: (state, revision) =>
        DateTime.now.pipe(
          Effect.flatMap((now) =>
            transaction
              .update(salesPipelineStates)
              .set({ revision: revision + 1, state, updatedAt: DateTime.toDateUtc(now) })
              .where(and(whereScope, eq(salesPipelineStates.revision, revision)))
              .returning({ revision: salesPipelineStates.revision })
              .pipe(Effect.mapError(unavailable)),
          ),
        ),
    });
    /**
     * AI level C. Proposing needs only read access (the agent principal has no write grant, so it can never change an
     * opportunity directly); deciding and reverting need write_all and a person (command guard).
     */
    const applyAi = Effect.fn('SalesPipeline.applyAi')(function* applyAi(
      command: Extract<
        SalesPipelineCommand,
        { readonly _tag: 'AiDecideChanges' | 'AiProposeChanges' | 'AiRevertBatch' }
      >,
      expectedRevision: number,
      invocationId: string,
    ) {
      const snapshot = yield* load();
      if (snapshot.revision !== expectedRevision) {
        return yield* new SalesPipelineRevisionConflict({
          code: 'sales_pipeline_revision_conflict',
          reason: revisionConflictReason,
        });
      }
      const now = yield* DateTime.now;
      const outcome = yield* applySalesPipelineAiCommand(
        snapshot.state,
        command,
        { invocationId, now, principalId: scope.principalId },
        evolveOpportunityState,
      ).pipe(
        Effect.mapError((failure) =>
          failure.kind === 'not_found'
            ? new SalesPipelineNotFound({ code: 'sales_pipeline_not_found', reason: failure.message })
            : new SalesPipelineLifecycleConflict({
                code: 'sales_pipeline_lifecycle_conflict',
                reason: failure.message,
              }),
        ),
      );
      if (outcome.state === snapshot.state) {
        const unchanged: AppliedCommand = {
          changedAt: now,
          result: { entityIds: [...outcome.entityIds], opportunities: [], revision: expectedRevision },
          stageChanges: [],
        };
        return unchanged;
      }
      const previous = new Map(snapshot.state.opportunities.map((entry) => [entry.id, entry] as const));
      const affected = outcome.state.opportunities.filter((entry) => previous.get(entry.id) !== entry);
      // Approved (or reverted) stage moves publish the same stage-changed Outbox Message as a manual move.
      const stageChanges: StageChange[] = affected.flatMap((opportunity): StageChange[] => {
        const before = previous.get(opportunity.id);
        if (before === undefined) {
          return [{ fromStage: Option.none(), opportunity }];
        }
        return before.stage === opportunity.stage ? [] : [{ fromStage: Option.some(before.stage), opportunity }];
      });
      const revision = yield* save(expectedRevision, outcome.state);
      const applied: AppliedCommand = {
        changedAt: now,
        result: { entityIds: [...outcome.entityIds], opportunities: affected, revision },
        stageChanges,
      };
      return applied;
    });
    const apply = Effect.fn('SalesPipeline.apply')(function* apply(
      command: SalesPipelineCommand,
      expectedRevision: number,
      invocationId: string,
    ) {
      if (
        prepared === undefined ||
        prepared.actionInvocationId !== invocationId ||
        prepared.payload.expectedRevision !== expectedRevision ||
        !sameCommand(prepared.payload.command, command)
      ) {
        return yield* referenceUnavailable();
      }
      const entrusted = entrustedPrincipalOf(command);
      if (entrusted !== undefined) {
        const directory = yield* loadAssignablePrincipalDirectory(transaction, scope).pipe(
          Effect.mapError(referenceUnavailable),
        );
        yield* activeAssignmentMember(directory, entrusted).pipe(
          Effect.catchTag('AssigneeIneligible', () =>
            Effect.fail(
              new SalesPipelineReferenceIneligible({
                code: 'sales_pipeline_reference_ineligible',
                reason: 'The entrusted principal is no longer active in this company',
              }),
            ),
          ),
        );
      }
      if (isSalesPipelineAiCommand(command)) {
        return yield* applyAi(command, expectedRevision, invocationId);
      }
      const snapshot = yield* load();
      if (snapshot.revision !== expectedRevision) {
        return yield* new SalesPipelineRevisionConflict({
          code: 'sales_pipeline_revision_conflict',
          reason: revisionConflictReason,
        });
      }
      const now = yield* DateTime.now;
      const change = yield* evolveOpportunityState(snapshot.state, command, { invocationId, now });
      const results = change.results === undefined ? {} : { results: [...change.results] };
      // A bulk command that changed nothing is not persisted and keeps the current revision.
      if (change.affected.length === 0) {
        const unchanged: AppliedCommand = {
          changedAt: now,
          result: { opportunities: [], revision: expectedRevision, ...results },
          stageChanges: [],
        };
        return unchanged;
      }
      const revision = yield* save(expectedRevision, change.state);
      const applied: AppliedCommand = {
        changedAt: now,
        result: { opportunities: [...change.affected], revision, ...results },
        stageChanges: change.stageChanges,
      };
      return applied;
    });
    /** The records read's whole transaction step: the raw state row; {@link finishSalesPipelineRecords} decodes it. */
    const loadRecords = (
      grants: SalesPipelineRecordsGrants,
      request: RecordsRequest = {},
    ): Effect.Effect<LoadedSalesPipelineRecords, SalesPipelinePersistenceUnavailable> => {
      const historySource = sql`${salesPipelineStates.state}->'aiChanges'`;
      const history =
        request.agentHistory === undefined
          ? undefined
          : agentHistoryPageSql(historySource, 'sales-pipeline', request.agentHistory);
      let state = sql`jsonb_build_object('opportunities', '[]'::jsonb)`;
      if (grants.predicate !== undefined) {
        if (grants.readAll && request.agentHistory !== undefined) {
          state = sql`jsonb_build_object('opportunities', '[]'::jsonb, 'aiChanges', ${history})`;
        } else {
          const reach = opportunityReachSql(grants.predicate, sql`opportunity`, scope.tenantId);
          const metadata = grants.readAll ? sql`${salesPipelineStates.state} - 'opportunities'` : sql`'{}'::jsonb`;
          state = sql`jsonb_build_object('opportunities', (select coalesce(jsonb_agg(opportunity), '[]'::jsonb) from jsonb_array_elements(coalesce(${salesPipelineStates.state}->'opportunities', '[]'::jsonb)) as opportunity where ${reach})) || ${metadata}`;
        }
      }
      return transaction
        .select({ revision: salesPipelineStates.revision, state })
        .from(salesPipelineStates)
        .where(whereScope)
        .limit(1)
        .pipe(
          Effect.mapError(unavailable),
          Effect.map(([row]) => Option.fromUndefinedOr(row)),
        );
    };
    return { apply, loadRecords };
  },
  Effect.mapError((cause) =>
    Object.defineProperty(
      new OperationContextUnavailable({
        code: 'operation_context_unavailable',
        reason: 'Owner-scoped services are temporarily unavailable',
      }),
      'cause',
      { enumerable: false, value: cause },
    ),
  ),
);
